css.content:
/* Animated list: opacity-only entrance staggered by (index * step); items hold their space so nothing shifts. */
.animated-list { list-style: none; margin: 0; padding: 0; }
.animated-list-item { animation: animated-list-in var(--slow) var(--ease) both; animation-delay: calc(var(--i) * var(--animated-list-step, 300ms)); }
@keyframes animated-list-in { from { opacity: 0; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .animated-list-item { animation: none; } }

usage:
import {AnimatedList} from '@monoline/react';

const row = (t: string, d: string) => (
  <div style={{display: 'grid', gap: 'var(--s1)', padding: 'var(--s3) var(--s4)', border: '1px solid var(--rule)'}}>
    <strong>{t}</strong><span style={{color: 'var(--muted)', fontSize: 'var(--text-sm)'}}>{d}</span>
  </div>
);

<AnimatedList style={{display: 'grid', gap: 'var(--s2)', maxWidth: '24rem'}}>
  {row('Build passed', 'main, 2 minutes ago')}
  {row('Review requested', 'Docs update, 5 minutes ago')}
  {row('Deploy finished', 'Production, 9 minutes ago')}
</AnimatedList>

source.content:
import {Children, forwardRef, type CSSProperties, type HTMLAttributes} from 'react';
import {cx} from '../../utils/cx';

export interface AnimatedListProps extends HTMLAttributes<HTMLUListElement> {
  /** Milliseconds between one item entering and the next. Default 300. */
  interval?: number;
}

/**
 * A list whose items fade in one after another when it mounts. Every item holds its place from the first frame (opacity only),
 * so nothing shifts. A real `<ul>`; one item per child. Static under reduced motion.
 */
export const AnimatedList = forwardRef<HTMLUListElement, AnimatedListProps>(function AnimatedList({interval = 300, className, style, children, ...rest}, ref) {
  return (
    <ul ref={ref} className={cx('animated-list', className)} style={{'--animated-list-step': `${interval}ms`, ...style} as CSSProperties} {...rest}>
      {Children.toArray(children).map((child, i) => (
        <li key={i} className="animated-list-item" style={{'--i': i} as CSSProperties}>{child}</li>
      ))}
    </ul>
  );
});
